constexpr const wchar_t* k_de_Text3 = L"Viele Abenteurer haben mir erz\u00e4hlt, dass der Klang der Harfe sie beruhigt und ihre M\u00fcdigkeit vertreibt. Ben\u00f6tigt Ihr meine Hilfe?";
constexpr const wchar_t* k_de_Text4 = L"Seid gegr\u00fc\u00dft! Mein Name ist Baz und ich bin der Lagerverwalter. Ich kann Euch helfen, wohin Ihr auch geht. Z\u00f6gert nicht, Eure Habseligkeiten bei mir zu lassen.";
constexpr const wchar_t* k_de_Text5 = L"Habt Ihr genug Geld dabei? Ohne Gold kann ich die Gegenst\u00e4nde nicht kombinieren, denn meine Forschung verlangt nach Mitteln. Verstanden? Wollt Ihr wissen, wie viel Gold ben\u00f6tigt wird?";
constexpr const wchar_t* k_de_Text6 = L"Willkommen in MU! Dr\u00fcckt die F1-Taste, falls Ihr auf Euren Reisen \u00fcber den Kontinent von MU Hilfe ben\u00f6tigt.";
constexpr const wchar_t* k_de_Text7 = L"Seid Ihr zum ersten Mal in Lorencia? Geht zum s\u00fcd\u00f6stlichen Ausgang vor dem Brunnen und versucht Euch an Budge-Drachen oder Spinnen. Die Skelette im Nordwesten sind zu gef\u00e4hrlich.";
constexpr const wchar_t* k_de_Text8 = L"Willkommen in Noria. Wenn Ihr zum ersten Mal hier seid, geht am Tresorw\u00e4chter vorbei und nehmt den S\u00fcdausgang. Versucht Euch an schwachen Monstern wie Skorpionen oder Goblins.";
constexpr const wchar_t* k_de_Text9 = L"Wenn Ihr eine ausf\u00fchrliche Anleitung zum Kontinent MU ben\u00f6tigt, besucht http://muonline.webzen.net";
constexpr const wchar_t* k_de_Text50 = L"Die 'Schriftrolle des Kaisers', die von Muren, dem ersten Kaiser von MU, berichtet, soll im Verlorenen Turm, in Atlans und im Dungeon gesichtet worden sein.";
