constexpr const wchar_t* k_de_Text76 = L"Von da an entstand der Brauch, dass dunkle Ritter, die Klingenritter werden wollten, ihre Schwerter zerbrachen - als Symbol des Gel\u00fcbdes, ihre Klinge niemals ungerecht zu f\u00fchren.";
