constexpr const wchar_t* k_de_Text78 = L"Dies wird die 'Tr\u00e4ne der Elfe' genannt, und die Elfe, die diesen Stein findet, wird zur Musen-Elfe und vermag die Macht der elfischen G\u00f6ttinnen heraufzubeschw\u00f6ren.";
constexpr const wchar_t* k_de_Answer78Slot0 = L"Ich bin zur Musenelfe geworden!";
