constexpr const wchar_t* k_de_Answer79Slot0 = L"Ich bin zum Klingenritter geworden!";
constexpr const wchar_t* k_de_Text80 = L"Nachdem das Reich vereint war, schworen die Menschen dem Kaiser ihre Treue. Einige der Sch\u00e4tze, die als Zeichen ihrer Loyalit\u00e4t dargebracht wurden, sind die folgenden.";
