constexpr const wchar_t* k_de_Text117 = L"Ihr habt es nicht vermocht, ein Blade Knight zu werden. Kehrt zur\u00fcck, wenn Ihr durch den 'Ring des Ruhms' neue Kraft erlangt habt.";
