constexpr const wchar_t* k_de_Answer132Slot0 = L"Ach wirklich!";
constexpr const wchar_t* k_de_Text133 = L"Der 'Ring des Ruhms' entstand, als die Prophezeiung Secromicon aus einem unverg\u00e4nglichen Metall geschaffen wurde. Beide galten als heilig, doch ihr Verbleib wurde unbekannt, als sie w\u00e4hrend des Aufstands des stellvertretenden Befehlshabers Gaion entwendet wurden.";
constexpr const wchar_t* k_de_Answer133Slot0 = L"Ist das so!";
constexpr const wchar_t* k_de_Text134 = L"Nun, da der 'Ring des Ruhms' gefunden wurde, werdet Ihr als Krieger noch weiter wachsen k\u00f6nnen.";
