constexpr const wchar_t* k_de_Text135 = L"Wenn Ihr neue Macht erlangen wollt, h\u00f6rt mir gut zu. Der 'Dunkle Stein', der Kriegern neue Macht verleihen soll, wurde auf dem Kontinent Mu gefunden.";
