constexpr const wchar_t* k_de_Text137 = L"Es hei\u00dft, man k\u00f6nne den Stein in Tarkan und Icarus finden. H\u00fctet Euch vor den Monstern. Jene Monster, die den Stein in sich tragen, regieren nur auf solche, die eine besondere Gabe besitzen.";
